c语言中字符串的基础知识 经常忘记字符串相关的内容，作笔记整理如下。 定义 字符数组定义 char c [ 20 ] = &quot;Hello World!&quot; ; //可不用完 char s [ 20 ]; //不赋值 char cs [] = &quot;Hello, World!&quot; ; 字符指针 char * s = &quot;Hello, World!&quot; ; //常量，不可变 动态分配 #include &lt;stdlib.h&gt; char * str = ( char * ) malloc ( 100 * sizeof ( char )); //需要free(str);定义中100可以换位变量 输入 读到空格前 scanf ( &quot;%s&quot; , &amp; s ); //最为简单 读取整行 char sentence [ 100 ]; fgets ( sentence , sizeof ( sentence ), stdin ); // 读取整行，包含换行符 删去换行符： if ( str [ strlen ( str ) -1 ] == &#39;
&#39; ) str [ strlen ( str ) -1 ] = &#39;\0&#39; ; scanf读整行 scanf ( &quot;%[^ 
 ]&quot; , s ); getchar (); //消耗这个换行符 scanf ( &quot;%[^ 
 ]%*c&quot; , s ); //自动丢弃换行符，*表示不存储 输出 printf ( &quot;%s&quot; , s ); //没有换行 puts ( s ); //自带换行 其他函数 复制 strcpy ( str1 , str2 ); //将str2赋值给str1 拼接 strcat ( str1 , str2 ); //将str2接在str1末尾 比较 int cmp = strcmp ( str1 , str2 ); //逐个字符比较ASCLL码值，负数代表str1&lt;str2，0代表str1=str2，正数代表str1&gt;str2

技术知识点 在线 C 语言编译器 Monaco Editor 集成 项目未使用打包工具，直接通过 CDN 提供的 AMD loader 引入 Monaco： require . config ({ paths : { vs : &#39;https://cdnjs.cloudflare.com/ajax/libs/monaco-editor/0.33.0/min/vs&#39; } }); require ([ &#39;vs/editor/editor.main&#39; ], () =&gt; { window . editor = monaco . editor . create ( document . getElementById ( &#39;editor&#39; ), { value : DEFAULT_CODE , language : &#39;c&#39; , theme : localStorage . getItem ( &#39;editorTheme&#39; ) === &#39;light&#39; ? &#39;vs-light&#39; : &#39;vs-dark&#39; , automaticLayout : true , minimap : { enabled : false }, fontSize : 13 }); }); 重点：使用 automaticLayout 保障窗口缩放时不需要手动 layout ；使用 window.editor.trigger 绑定撤销/重做、注释切换等命令；通过 CSS 控制整体暗/明主题。 面试补充：相比 textarea ，Monaco 自带语法折叠、多光标、命令面板，提升在线编译器体验；项目中测试过 Chrome/Safari/Edge 的中文输入法，未出现光标漂移。 智能缩进 / 格式化 采用自定义的 smartCIndent 函数，对每行代码建立状态机，核心规则： 维护块栈统计 {} 层级； 为 case/default 、 do...while 设置专属分支避免误缩； 遍历时跳过字符串、注释，保证内部花括号不干扰。 function smartCIndent ( code , tabSize = 4 ) { const lines = code . split ( /?
/ ); let indent = 0 ; let inBlockComment = false , inString = false , stringChar = &#39;&#39; ; return lines . map (( line ) =&gt; { const trimmed = line . trim (); if ( trimmed . startsWith ( &#39;}&#39; )) indent = Math . max ( 0 , indent - 1 ); const formatted = &#39; &#39; . repeat ( tabSize * indent ) + trimmed ; // ...扫描字符更新 indent / 状态... if ( trimmed . endsWith ( &#39;{&#39; )) indent += 1 ; return formatted ; }). join ( &#39;
&#39; ); } 面试补充：若老师问为何不用 AST，可以说明 AST 解析器体积大且需要完整 C 标准库；纯栈 + 状态机已经覆盖主流语法结构，成本更低。 浏览器持久化策略 使用多个 localStorage Key 分别记录代码、主题、测试用例： localStorage . setItem ( &#39;deepseek_saved_c&#39; , window . editor . getValue ()); localStorage . setItem ( &#39;editorTheme&#39; , isDark ? &#39;dark&#39; : &#39;light&#39; ); localStorage . setItem ( &#39;test_cases_v1&#39; , JSON . stringify ( cases )); 页面加载时先读取存档，fallback 到默认模板；在 beforeunload 事件中追加自动保存，减少意外丢失。 面试补充：Safari 隐私模式会抛出 QuotaExceededError ，因此所有写操作都包裹 try...catch 并在 UI 提醒用户。 Wandbox API 调用 运行按钮触发 tryWandboxCompile ，内部实现： const wandboxUrl = &#39;https://wandbox.org/api/compile.json&#39; ; const resp = await fetch ( wandboxUrl , { method : &#39;POST&#39; , headers : { &#39;Content-Type&#39; : &#39;application/json&#39; }, body : JSON . stringify ({ code , compiler : &#39;gcc-head&#39; , stdin }) }); const json = await resp . json (); const out = ( json . program_output || &#39;&#39; ) + ( json . program_error ? `
[stderr]
 ${ json . program_error } ` : &#39;&#39; ); stdoutEl . textContent = ` ${ out } 
[exit code] ${ json . status ?? 0 } ` ; 若请求失败（超时 / 网络 / HTTP 错误），直接在输出面板显示真实错误信息并写入控制台，无本地 WASM 回退，用真实情况教育用户。 面试补充：通过 Promise.race + 手动超时避免长时间等待；在测试用例批量运行里沿用同一 API，统一错误处理经验。 URL hash 分享 分享弹窗会把数据打包成 JSON 再 Base64： function buildShareUrl ( opts ) { const payload = { code : window . editor . getValue (), stdin : opts . stdin ? stdinEl . value : undefined , cases : opts . cases ? cases : undefined , name : currentFilename }; const b64 = btoa ( unescape ( encodeURIComponent ( JSON . stringify ( payload )))); return ` ${ location . origin }${ location . pathname } #share= ${ b64 } ` ; } 页面加载检查 location.hash ，若识别到 #share= 前缀就解码恢复编辑器、stdin 和测试用例。 面试补充：Base64 长度比原文短一截，但仍受浏览器 URL 长度限制；所以 UI 中提示“过长建议下载文件”。 Service Worker / PWA 手写 sw.js 维护固定版本号，核心策略是 precache + cache-first： const CACHE_NAME = `c-compiler- ${ VERSION } ` ; self . addEventListener ( &#39;fetch&#39; , ( event ) =&gt; { if ( event . request . method !== &#39;GET&#39; ) return ; event . respondWith ( caches . match ( event . request ). then (( cached ) =&gt; cached || fetch ( event . request ). then (( resp ) =&gt; { if ( resp . status === 200 ) caches . open ( CACHE_NAME ). then (( cache ) =&gt; cache . put ( event . request , resp . clone ())); return resp ; }). catch (() =&gt; caches . match ( event . request ))) ); }); 安装阶段缓存首页、Manifest、图片；激活时清理旧版本缓存，并在离线时返回友好文本提示。 面试补充：没有借助 Workbox，便于完全掌控缓存逻辑；通过 scripts/version.js 的版本号手动触发缓存刷新。 GitHub Pages 发布 项目无构建链路，直接把静态资源放在主分支根目录，GitHub Pages 自动部署。若要更新，只需 git push 主分支。 面试补充：若老师问自动化，可说明未来计划增加轻量工作流生成压缩版资源；目前重点是快速迭代前端功能。 AI 医学辅助诊断系统 多 Agent 协同流程 SymptomAnalyzer 将一次分析拆成搜索计划、证据检索、证据排序、临床规划、追问、中文翻译六个阶段，每个阶段都用 DeepSeek Agent + JSON Schema 约束输出结构。 result , raw = await self . _run_agent ( agent_name = &quot;ClinicalPlannerAgent&quot; , system_prompt = &quot;You design safe, evidence-aware triage plans for telemedicine workflows.&quot; , instructions = instructions , schema = schema , context = context , temperature = 0.2 , ) 每个 Agent 的原始输出与结构化结果都会记录在 agent_traces ，方便面试时解释“如何保证可追溯性”。当 LLM 返回空值或证据不足时，代码回退到预置安全方案，确保 API 不会直接返回空响应。 PubMed/NICE 抓取与过滤 knowledge.py 直接调用 NCBI E-utilities（ esearch / esummary / efetch ），并对返回文献做人口、物种和研究类型过滤： 年龄段：根据患者年龄组构建包含/排除词，例如成人病例会自动排除 neonatal 、 pediatric 。 物种：串联 HUMAN_ONLY_FILTER 、 VETERINARY_FILTER 和关键词黑名单（ canine 、 vet journal 等）。 研究类型：优先保留指南、系统综述等高质量文献，检索不到时再回退到病例报告。 if item . category and &quot;guideline&quot; in item . category . lower (): category_bonus = 0.25 guideline_priority = True 同时抓取 NICE 官方指南 HTML，提取标题、摘要和 PDF 链接，与 PubMed 结果合并后统一排序。 证据打分与可视化 _rank_evidence 使用词覆盖度、证据新鲜度、研究类型、实验室指标匹配等特征打分，并给指南附加优先级；最终分数写回 EvidenceItem.score 。 _build_visualizations 将文献按年份聚合生成 ChartDatum 列表，前端据此渲染“年份柱状图 + 来源占比圆图”。这部分是手写 CSS 图表，面试时可强调“无第三方图表库，也能快速实现轻量可视化”。 前端状态编排 主页面 page.tsx 使用 React hooks 管理病例列表、追问草稿、分析结果、折叠状态，并通过 localStorage 在刷新后恢复： const payload = { cases , caseCounter , activeCaseIndex , analyses : caseAnalyses , followupHistory , collapsedCases }; localStorage . setItem ( CASE_STORAGE_KEY , JSON . stringify ( payload )); 一旦收到 analysis.requires_followup=true ，界面会锁定结果区，展示追问列表并记录历史追问轮次；补充回答后再调用 /api/v1/analyze 生成最终方案。 进度追踪与下载接口 每次请求在后台注册进度令牌，前端通过 setInterval 调用 /api/v1/progress/:token 显示实时进度条。 download_pubmed_asset 根据 PMID 调用 PubMed API 获取摘要或全文 PDF URL，封装成二进制响应返回前端，支持一键下载文献。 部署与调试 项目提供 deploy.sh ，根据 git diff 判断本次需要同步的模块，并通过 systemd 重启 medagt-api （FastAPI）和 medagt-web （Next.js）。 日志分散在前端浏览器控制台与后端 logging 输出，调试 Agent 行为时可以直接查看 agent_traces ，定位是检索、排序还是规划阶段出现偏差。 说明：这种结构化格式方便后端做校验，例如检查 severity 是否在 mild/moderate/severe 范围内。老师如果问到...

AIOps Python实战学习 main.py 导入 &amp; 项目根目录 pandas 用来读csv； OrderedDict （来自 typing，不过更常用的是 collections.OrderedDict ）用来构造有序字典； project_root 获取当前文件所在目录，用于拼接 input/ 和 output/ 的路径。 掌握点： 模块导入： import ... , from ... import ... os.path 用法（dirname,abspath,join) 终止条件 max_messages_termination = MaxMessageTermination ( max_messages = 20 ) termination = max_messages_termination 这两行是为 GraphFlow / GroupChat 设置一个终止条件： 对话最多 20 条消息，超过就停。 主函数 main()（异步） async def main (): input_path = os . path . join ( project_root , &#39;input&#39; , &#39;input_timestamp.csv&#39; ) df_input_timestamp = pd . read_csv ( input_path , encoding = &#39;utf-8&#39; ) for index , row in df_input_timestamp . iterrows (): if index &lt; 32 : continue 这是一个 async def ，说明里面会有 await 调用（例如调用 LLM 的异步接口）； pd.read_csv 把 CSV 读成一个 DataFrame ； df_input_timestamp.iterrows() 逐行遍历： index 是行号； row 是这一行的数据（Series）。 if index &lt; 32: continue ：跳过前 32 行，只处理后面的 case。 掌握点: for index, row in df.iterrows() 的用法； continue 的含义（跳过本次循环剩余部分）。 从每一行取字段 print ( &quot;&gt;&gt;&quot; * 100 ) print ( f &quot;index: { index } &quot; ) start_timestamp = row [ &#39;start_timestamp&#39; ] end_timestamp = row [ &#39;end_timestamp&#39; ] start_time_hour = row [ &#39;start_time_hour&#39; ] uuid = row [ &#39;uuid&#39; ] - 使用 row['列名'] 取出这一行的几个关键字段； - f"index: {index}" 是 f-string ，格式化输出。 日志 refinement + 日志 LLM 提炼 refined_logs = log_refinement ( start_time_hour , start_timestamp , end_timestamp ) if refined_logs is not None : print ( &#39;//&#39; * 20 ) refined_logs = await logs_agent . run ( task = f &quot;请提炼出以下日志中对故障诊断最关键、最有价值的日志： 
 { refined_logs } &quot; ) refined_logs = refined_logs . messages [ - 1 ] . content else : refined_logs = None print ( &#39;logs refinement completed!&#39; ) - log_refinement(...) 返回某个时间窗口的日志内容（已经过预筛）； 如果不是 None： 使用 `logs_agent.run(task=...)` 让日志 Agent 调用 LLM，拿到一个对话结果对象（里面有 messages 列表）。 `refined_logs.messages[-1].content` 取最后一条消息（LLM 的最终回答）的文本内容。 否则就保持 None。 掌握点 await 的含义（协程调用）； 对象属性访问：foo.bar.baz； 列表索引 [-1] 表示最后一个元素。 trace refinement + Agent 提炼 refined_traces , trace_unique_dict , status_combinations_csv = trace_refinement ( start_time_hour , start_timestamp , end_timestamp ) if refined_traces is not None or status_combinations_csv is not None : print ( &#39;//&#39; * 20 ) refined_traces = await traces_agent . run ( task = f &quot;请提炼出以下trace中对故障诊断最关键、最有价值的traces： 
 { refined_traces } 
 { status_combinations_csv } &quot; ) refined_traces = refined_traces . messages [ - 1 ] . content else : refined_traces = None print ( &#39;traces refinement completed!&#39; ) 这里 trace_refinement 返回三个东西： - refined_traces ：预处理后的 trace； - trace_unique_dict ：可能是去重后的 trace 信息（这里没再用）； - status_combinations_csv ：某些状态组合的信息（转成文本？）。 如果两者之一不为空，就拼接起来扔给 traces_agent 处理。 metrics refinement + Agent 提炼 略 构造多模态分析 prompt multimodal_prompt = get_multimodal_analysis_prompt ( log_data = refined_logs , trace_data = refined_traces , metric_data = refined_metrics ) 这个函数应该是把三个模态的信息按照某个模板组合成一个大的任务描述，给 orchestrator agent 用。 构建 Agent 对话图（Graph） builder = DiGraphBuilder () builder . add_node ( orchestration_agent ) builder . add_node ( ad_agent ) . add_node ( ft_agent ) . add_node ( rcl_agent ) builder . add_node ( reflection_agent ) . add_node ( summarization_agent ) builder . add_edge ( orchestration_agent , ad_agent ) builder . add_edge ( orchestration_agent , ft_agent ) . add_edge ( ad_agent , ft_agent ) builder . add_edge ( orchestration_agent , rcl_agent ) . add_edge ( ft_agent , rcl_agent ) builder . add_edge ( ad_agent , reflection_agent ) . add_edge ( ft_agent , reflection_agent ) . add_edge ( rcl_agent , reflection_agent ) builder . add_edge ( reflection_agent , orchestration_agent , condition = lambda msg : &quot;APPROVE&quot; not in msg . to_model_text ()) builder . add_edge ( reflection_agent , summarization_agent , condition = lambda msg : &quot;APPROVE&quot; in msg . to_model_text ()) builder . set_entry_point ( orchestration_agent ) graph = builder . build () 这里使用 DiGraphBuilder 构造一个有向图： - 节点是不同的 agent ； - 边表示“谁把消息发给谁”； - 最后两条边用 condition 决定从 reflection 分流到 orchestration 或 summarization ： - 如果消息里不含 "APPROVE" ：回到 orchestrator 继续迭代； - 如果含 "APPROVE" ：进入 summarization ，总结最终答案。 掌握点 lambda 表达式 lambda msg: ... ； 链式调用 builder.add_edge(...).add_edge(...) 是什么含义（返回 builder 自己）。 创建 GraphFlow 团队并运行 team = GraphFlow ( participants = [ orchestration_agent , ad_agent , ft_agent , rcl_agent , reflection_agent , summarization_agent ], graph = graph , termination_condition = termination , ) await team . reset () # await Console(team.run_stream(task=f&quot;{multimodal_prompt}&quot;)) respose = await team . run ( task = f &quot; { multimodal_prompt } &quot; ) - GraphFlow 用刚才的图 + agent 列表构建一个团队； - await team.reset() 重置对话状态； - team.run(task=...) 运行任务一次，并得到一个包含消息历史的结果对象。 （注：respose 这个变量名有点小拼写错误，正常应该是 response，但不影响运行。） 从结果里抓 JSON，解析并写文件 result = re . search ( r &#39;(\{.*\})&#39; , respose . messages [ - 1 ] . content , re . DOTALL ) if result : result = result . group ( 1 ) else : result = None json_result = json . loads ( result ) result_data = OrderedDict () result_data [ &quot;component&quot; ] = json_result . get ( &quot;component&quot; , &quot;&quot; ) result_data [ &quot;uuid&quot; ] = uuid result_data [ &quot;reason&quot; ] = json_result . get ( &quot;reason&quot; , &quot;&quot; ) result_data [ &quot;reasoning_trace&quot; ] = json_result . get ( &quot;reasoning_trace&quot; , []) result_list_path = os . path . join ( project_root , &#39;output&#39; , &#39;results_list.json&#39; ) with open ( result_list_path , &#39;a&#39; , encoding = &#39;utf-8&#39; ) as f : json . dump ( result_data , f ) f . write ( &#39; 
 &#39; ) print ( f &quot;第 { index + 1 } 条数据处理完成&quot; ) - respose.messages[-1].content ：取最后一条消息文本； - re.search(r'(\{.*\})', ..., re.DOTALL) ： - 用正则在这段文本里找一个“从第一个 { 到最后一个 } 的大块字符串”； - re.DOTALL 让 . 能匹配换行符。 - json.loads(result) ：把 JSON 字符串变成 Python 字典； - OrderedDict() ：按顺序插入字段； - 写入文件时用 'a' 模式，表示“追加写入”，每一行写一个 JSON + 换行。 掌握点 - 正则表达式 re.search 的基本用法； - json.loads / json.dump； - with op...
